package com.collegeerp.erp.audit.entity;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.collegeerp.erp.audit.enums.*; import com.collegeerp.erp.college.entity.College; import com.collegeerp.erp.common.entity.BaseAuditEntity; import com.collegeerp.erp.user.entity.User; import jakarta.persistence.*;
@JsonIgnoreProperties({"actorUser","college"})
@Entity @Table(name="audit_logs",indexes={@Index(name="idx_audit_created",columnList="created_at"),@Index(name="idx_audit_college",columnList="college_id")}) public class AuditLog extends BaseAuditEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="actor_user_id") private User actorUser; private String actorName; private String actorEmail; @Column(length=300) private String actorRoles; @ManyToOne(fetch=FetchType.LAZY) private College college; @Enumerated(EnumType.STRING) @Column(nullable=false) private AuditModule module; @Enumerated(EnumType.STRING) @Column(nullable=false) private AuditAction action; private String entityType; private Long entityId; @Column(nullable=false,length=1000) private String description; private String ipAddress; @Column(length=500) private String userAgent;
public Long getId(){return id;} public User getActorUser(){return actorUser;} public void setActorUser(User v){actorUser=v;} public String getActorName(){return actorName;} public void setActorName(String v){actorName=v;} public String getActorEmail(){return actorEmail;} public void setActorEmail(String v){actorEmail=v;} public String getActorRoles(){return actorRoles;} public void setActorRoles(String v){actorRoles=v;} public College getCollege(){return college;} public void setCollege(College v){college=v;} public AuditModule getModule(){return module;} public void setModule(AuditModule v){module=v;} public AuditAction getAction(){return action;} public void setAction(AuditAction v){action=v;} public String getEntityType(){return entityType;} public void setEntityType(String v){entityType=v;} public Long getEntityId(){return entityId;} public void setEntityId(Long v){entityId=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public void setIpAddress(String v){ipAddress=v;} public void setUserAgent(String v){userAgent=v;} }
